base=pathlib.Path("/private/tmp/localos-git-history-verified-20260921.qZcoBF")
ep=pathlib.Path(".agent/tasks/production-readiness-20260917/evidence")
report=json.loads((base/"tree-blobs-redacted.json").read_text())
meta=json.loads((ep/"git-all-refs-tree-blobs-metadata-20260921.json").read_text())["findings"]
manifest=json.loads((ep/"git-all-refs-manifest-20260921.json").read_text())
env={"PATH":"/usr/bin:/bin","GIT_NO_REPLACE_OBJECTS":"1","GIT_CONFIG_NOSYSTEM":"1","GIT_CONFIG_GLOBAL":"/dev/null","GIT_TERMINAL_PROMPT":"0"}
roots=list(dict.fromkeys([p["tree"] for r in meta for p in r["locations"]]+manifest["commitTips"]))
cache={}; rows=[]
for i in [13,*range(16,40)]:
 f=report[i-1]; raw=(base/"tree-only-blobs"/pathlib.Path(f["File"]).name).read_bytes(); text=raw.decode()
 line=text.splitlines()[f["StartLine"]-1]; parts=f["Match"].split("REDACTED")
 vals=set(m.group(1) for m in re.finditer(re.escape(parts[0])+r"(.+?)"+re.escape(parts[1]),line)); assert len(vals)==1
 v=next(iter(vals)); assert re.fullmatch("[0-9a-f]{64}",v)
 data=json.loads(text); paths=set()
 def walk(n):
  if isinstance(n,dict):
   for k,x in n.items():
    if x==v and isinstance(k,str) and re.fullmatch(r"(?:/app/)?(?:src|tests|frontend|scripts|alembic_migrations)/[A-Za-z0-9_./-]+",k): paths.add(k.removeprefix("/app/"))
    else: walk(x)
  elif isinstance(n,list):
   for x in n: walk(x)
 walk(data); assert paths
 hits=[]
 for path in sorted(paths):
  for root in roots:
   key=(root,path)
   if key not in cache:
    cp=subprocess.run(["/usr/bin/git","cat-file","blob",root+":"+path],env=env,capture_output=True,check=False)
    cache[key]=hashlib.sha256(cp.stdout).hexdigest() if cp.returncode==0 else None
   if cache[key]==v:
    hits.append({"git_root":root,"path":path}); break
 rows.append({"finding_id":i,"exact_line_match_bound":True,"declared_code_path_digest":True,"verified_against_git_source":bool(hits),"matching_sources":hits})
print(json.dumps({"rows":rows,"verified_findings":sum(r["verified_against_git_source"] for r in rows),"findings":len(rows),"git_lookups":len(cache),"roots_checked_max":len(roots),"values_withheld":True},indent=2))

